export function searchCourseCatalog(query, limit = 8) {
  if (!query || typeof query !== 'string') return [];
  const q = query.trim().toLowerCase();
  if (q.length === 0) return [];

  const results = [];
  const seen = new Set();

  for (const item of COURSE_CATALOG) {
    const nameMatch = item.name && item.name.toLowerCase().includes(q);
    const codeMatch = item.code && item.code.toLowerCase().includes(q);
    const catMatch = item.category && item.category.toLowerCase().includes(q);

    if (nameMatch || codeMatch || catMatch) {
      if (!seen.has(item.name)) {
        seen.add(item.name);
        // Prioritize exact prefix match
        const startsWith =
          (item.name && item.name.toLowerCase().startsWith(q)) ||
          (item.code && item.code.toLowerCase().startsWith(q));
        results.push({ ...item, startsWith });
      }
    }
  }

  // Sort: prefix matches first, then shorter names
  results.sort((a, b) => {
    if (a.startsWith && !b.startsWith) return -1;
    if (!a.startsWith && b.startsWith) return 1;
    return a.name.length - b.name.length;
  });

  return results.slice(0, limit);
}